// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address payer, uint256 targetBlock) public {
        vm.assume(payer != address(0));
        uint256 blk = bound(targetBlock, 1, type(uint64).max);

        vm.deal(payer, 100 ether);
        vm.prank(payer);
        (bool s,) = payable(address(c)).call{value: 10 ether}("");
        require(s);

        uint256 chosenBlk = blk;
        if (chosenBlk % 15 == 0) chosenBlk = chosenBlk + 1;
        vm.roll(chosenBlk);

        vm.warp(block.timestamp + 1);

        vm.deal(payer, 100 ether);
        vm.prank(payer);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok);

        assertTrue(address(c).balance > 0);
    }
}
